// ===== Oncode driver I/O (inlined by backend/seed/tools/lib/codegen.js) =====
// Input: one value per line in canonical form (see backend/seed/FORMAT.md). Output: canonical form.
namespace oncode {

// Nullable int, for level-order tree arrays such as [1,null,2].
struct Opt {
    bool has = false;
    int v = 0;
};

struct Reader {
    std::string s;
    size_t p = 0;
    Reader() {
        std::ios::sync_with_stdio(false);
        s.assign(std::istreambuf_iterator<char>(std::cin), std::istreambuf_iterator<char>());
    }
    [[noreturn]] void fail(const char* what) {
        std::cerr << "driver input error: " << what << " at byte " << p << "\n";
        std::exit(3);
    }
    void ws() {
        while (p < s.size() && std::isspace(static_cast<unsigned char>(s[p]))) p++;
    }
    bool peek(char c) {
        ws();
        return p < s.size() && s[p] == c;
    }
    void expect(char c) {
        if (!peek(c)) fail("unexpected character");
        p++;
    }
    long long integer(long long lo, long long hi) {
        ws();
        bool neg = false;
        if (p < s.size() && s[p] == '-') { neg = true; p++; }
        size_t start = p;
        long long v = 0;
        while (p < s.size() && std::isdigit(static_cast<unsigned char>(s[p]))) {
            if (p - start >= 18) fail("integer too long");
            v = v * 10 + (s[p++] - '0');
        }
        if (p == start) fail("expected integer");
        if (neg) v = -v;
        if (v < lo || v > hi) fail("integer out of range");
        return v;
    }
    void read(int& x) { x = static_cast<int>(integer(INT_MIN, INT_MAX)); }
    void read(long long& x) { x = integer(-999999999999999999LL, 999999999999999999LL); }
    void read(bool& x) {
        ws();
        if (s.compare(p, 4, "true") == 0) { x = true; p += 4; }
        else if (s.compare(p, 5, "false") == 0) { x = false; p += 5; }
        else fail("expected true or false");
    }
    void read(std::string& x) {
        expect('"');
        x.clear();
        while (p < s.size() && s[p] != '"') {
            if (s[p] == '\\') {
                p++;
                if (p >= s.size()) break;
            }
            x += s[p++];
        }
        if (p >= s.size()) fail("unterminated string");
        p++;
    }
    void read(Opt& o) {
        ws();
        if (s.compare(p, 4, "null") == 0) { o.has = false; p += 4; }
        else { o.has = true; o.v = static_cast<int>(integer(INT_MIN, INT_MAX)); }
    }
    void read(char& x) {
        std::string t;
        read(t);
        if (t.size() != 1) fail("expected one-character string");
        x = t[0];
    }
    template <class T> void read(std::vector<T>& v) {
        v.clear();
        expect('[');
        if (peek(']')) { p++; return; }
        for (;;) {
            T e;
            read(e);
            v.push_back(std::move(e));
            if (peek(',')) { p++; continue; }
            expect(']');
            return;
        }
    }
    void end() {
        ws();
        if (p != s.size()) fail("unexpected trailing input");
    }
};

struct Writer {
    std::string out;
    void write(int x) { out += std::to_string(x); }
    void write(long long x) { out += std::to_string(x); }
    void write(bool x) { out += x ? "true" : "false"; }
    void write(const std::string& x) {
        out += '"';
        for (char c : x) {
            if (c == '"' || c == '\\') out += '\\';
            out += c;
        }
        out += '"';
    }
    void write(char c) { write(std::string(1, c)); }
    void write(const Opt& o) {
        if (o.has) write(o.v);
        else out += "null";
    }
    template <class T> void write(const std::vector<T>& v) {
        out += '[';
        for (size_t i = 0; i < v.size(); i++) {
            if (i) out += ',';
            write(v[i]);
        }
        out += ']';
    }
    void line() { out += '\n'; }
    void flush() {
        std::fwrite(out.data(), 1, out.size(), stdout);
        std::fflush(stdout);
    }
};

}  // namespace oncode

int main() {
    oncode::Reader oc_in;
    vector<vector<int>> adjList;
    oc_in.read(adjList);
    oc_in.end();
    int n = (int)adjList.size();
    vector<Node*> oc_orig(n);
    for (int i = 0; i < n; i++) oc_orig[i] = new Node(i + 1);
    for (int i = 0; i < n; i++)
        for (int v : adjList[i]) oc_orig[i]->neighbors.push_back(oc_orig[v - 1]);
    unordered_set<Node*> oc_originals(oc_orig.begin(), oc_orig.end());
    Solution oc_sol;
    Node* oc_res = oc_sol.cloneGraph(n ? oc_orig[0] : nullptr);
    oncode::Writer oc_out;
    string oc_problem;
    vector<vector<int>> oc_adj(n);
    vector<Node*> oc_byVal(n + 1, nullptr);
    vector<Node*> oc_queue;
    if (oc_res) oc_queue.push_back(oc_res);
    unordered_set<Node*> oc_seen(oc_queue.begin(), oc_queue.end());
    for (size_t h = 0; h < oc_queue.size() && oc_problem.empty(); h++) {
        Node* x = oc_queue[h];
        if (oc_originals.count(x)) { oc_problem = "returned graph shares nodes with the original"; break; }
        if (x->val < 1 || x->val > n || (oc_byVal[x->val] && oc_byVal[x->val] != x)) { oc_problem = "clone has missing, extra or duplicate node values"; break; }
        oc_byVal[x->val] = x;
        for (Node* y : x->neighbors) {
            oc_adj[x->val - 1].push_back(y ? y->val : 0);
            if (y && !oc_seen.count(y)) { oc_seen.insert(y); oc_queue.push_back(y); }
        }
    }
    if (oc_problem.empty() && (int)oc_queue.size() != n) oc_problem = "clone has missing, extra or duplicate node values";
    for (auto& oc_l : oc_adj) sort(oc_l.begin(), oc_l.end());  // neighbour order does not matter
    if (oc_problem.empty()) oc_out.write(oc_adj);
    else oc_out.write(oc_problem);
    oc_out.line();
    oc_out.flush();
    return 0;
}

